#include "transpose.h"
#include <cuda_runtime.h>

/*
 * Optimized matrix transpose with shared memory padding to avoid bank conflicts.
 *
 * Key optimization:
 * - Adds one extra column of padding to shared memory (TILE_DIM + 1)
 * - This ensures that consecutive rows map to different banks
 * - Eliminates the 32-way serialization that occurred in the naive version
 *
 * When threads read tile[threadIdx.x][threadIdx.y], they access different rows
 * of the same column. With padding, these accesses map to different banks,
 * allowing parallel access instead of serialization.
 */

#define TILE_DIM 32

__global__ void k_transpose(const float* __restrict__ input,
                           float* __restrict__ output,
                           int N) {
    // Shared memory tile with padding to avoid bank conflicts
    // The extra column shifts each row's bank alignment
    __shared__ float tile[TILE_DIM][TILE_DIM + 1];

    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;

    // Read from global memory (coalesced)
    if (x < N && y < N) {
        tile[threadIdx.y][threadIdx.x] = input[y * N + x];
    }

    __syncthreads();

    // Write to global memory (transposed)
    // Calculate transposed position
    int tx = blockIdx.y * TILE_DIM + threadIdx.x;
    int ty = blockIdx.x * TILE_DIM + threadIdx.y;

    if (tx < N && ty < N) {
        // Now this access has no bank conflicts due to padding
        // Each thread accesses a different bank
        output[ty * N + tx] = tile[threadIdx.x][threadIdx.y];
    }
}
